import csv, io, json, os, sys
from datetime import date, datetime, timedelta, timezone
from zoneinfo import ZoneInfo


def read(d, name):
    p = os.path.join(d, name)
    if not os.path.exists(p):
        return []
    with open(p, encoding="utf-8-sig", newline="") as f:
        text = f.read()
    rows = []
    for r in csv.DictReader(io.StringIO(text)):
        r = {(k or "").strip(): (v or "").strip() for k, v in r.items() if k is not None}
        if any(r.values()):
            rows.append(r)
    return rows


def ftime(s):
    h, m, sec = s.split(":")
    return int(h) * 3600 + int(m) * 60 + int(sec)


def iso(ts, tz):
    dt = datetime.fromtimestamp(ts, tz)
    off = dt.utcoffset()
    secs = int(off.total_seconds())
    sign = "+" if secs >= 0 else "-"
    secs = abs(secs)
    return dt.strftime("%Y-%m-%dT%H:%M:%S") + "%s%02d:%02d" % (sign, secs // 3600, secs % 3600 // 60)


def main(inp, outp):
    with open(os.path.join(inp, "request.json"), encoding="utf-8-sig") as f:
        dates = sorted(set(json.load(f)["service_dates"]))
    agencies = read(inp, "agency.txt")
    agency_tz = {a["agency_id"]: a["agency_timezone"] for a in agencies}
    default_tz = agencies[0]["agency_timezone"]
    stops = {s["stop_id"]: s for s in read(inp, "stops.txt")}
    routes = {r["route_id"]: r for r in read(inp, "routes.txt")}
    trips = {t["trip_id"]: t for t in read(inp, "trips.txt")}
    cal = {c["service_id"]: c for c in read(inp, "calendar.txt")}
    exc = {}
    for e in read(inp, "calendar_dates.txt"):
        exc[(e["service_id"], e["date"])] = e["exception_type"]
    freqs = {}
    for fr in read(inp, "frequencies.txt"):
        freqs.setdefault(fr["trip_id"], []).append(fr)
    st = {}
    for r in read(inp, "stop_times.txt"):
        st.setdefault(r["trip_id"], []).append(r)

    days = ["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"]

    def runs(sid, d):
        e = exc.get((sid, d.strftime("%Y%m%d")))
        if e == "1":
            return True
        if e == "2":
            return False
        c = cal.get(sid)
        if not c:
            return False
        ds = d.strftime("%Y%m%d")
        return c["start_date"] <= ds <= c["end_date"] and c[days[d.weekday()]] == "1"

    def board_stop(sid):
        s = stops[sid]
        return s["parent_station"] if s.get("parent_station") else sid

    def btz(sid):
        z = stops[sid].get("stop_timezone")
        return ZoneInfo(z) if z else ZoneInfo(default_tz), z or default_tz

    # per-trip precompute
    pre = {}
    for tid, rows in st.items():
        if tid not in trips:
            continue
        rows = sorted(rows, key=lambda r: int(r["stop_sequence"]))
        times = [ftime(r["departure_time"] or r["arrival_time"]) if (r["departure_time"] or r["arrival_time"]) else None for r in rows]
        known = [i for i, t in enumerate(times) if t is not None]
        for a, b in zip(known, known[1:]):
            n = b - a
            for i in range(a + 1, b):
                times[i] = times[a] + (times[b] - times[a]) * (i - a) // n
        t = trips[tid]
        route = routes[t["route_id"]]
        label = route.get("route_short_name") or route.get("route_long_name") or ""
        last = stops[rows[-1]["stop_id"]]
        lname = stops[last["parent_station"]]["stop_name"] if last.get("parent_station") else last["stop_name"]
        deps = []
        for i, r in enumerate(rows[:-1]):
            if r["pickup_type"] == "1":
                continue
            hs = r.get("stop_headsign") or t.get("trip_headsign") or lname
            deps.append((times[i], r["stop_id"], hs))
        pre[tid] = (label, route["agency_id"], deps, times[0])

    boards = {}
    for sid, s in stops.items():
        if s.get("location_type", "") in ("", "0") and not s.get("parent_station") or s.get("location_type") == "1":
            for ds in dates:
                boards[(sid, ds)] = []

    for ds in dates:
        d = date.fromisoformat(ds)
        for tid, t in trips.items():
            if tid not in pre or not runs(t["service_id"], d):
                continue
            label, ag, deps, t0 = pre[tid]
            atz = ZoneInfo(agency_tz[ag])
            origin = int(datetime(d.year, d.month, d.day, 12, tzinfo=atz).timestamp()) - 43200
            for (tm, stop_id, hs) in deps:
                bs = board_stop(stop_id)
                tz, tzname = btz(bs)
                plat = stops[stop_id].get("platform_code") or None
                base = dict(route=label, headsign=hs, trip=tid, platform=plat, agency=ag)

                def add(kind, ts, until, hw):
                    x = dict(kind=kind, time=iso(ts, tz), until=iso(until, tz) if until is not None else None,
                             headway_secs=hw, **base)
                    boards[(bs, ds)].append((ts, x))
                if tid not in freqs:
                    add("scheduled", origin + tm, None, None)
                    continue
                off = tm - t0
                for fr in freqs[tid]:
                    s0, e0, h = ftime(fr["start_time"]), ftime(fr["end_time"]), int(fr["headway_secs"])
                    if s0 >= e0:
                        continue
                    k = (e0 - s0 - 1) // h
                    if fr.get("exact_times") == "1":
                        for j in range(k + 1):
                            add("scheduled", origin + s0 + j * h + off, None, None)
                    else:
                        add("interval", origin + s0 + off, origin + s0 + k * h + off, h)

    out = []
    for (sid, ds) in sorted(boards):
        deps = boards[(sid, ds)]
        deps.sort(key=lambda p: (p[0], p[1]["route"], p[1]["headsign"], p[1]["trip"],
                                 (0, "") if p[1]["platform"] is None else (1, p[1]["platform"])))
        out.append(dict(stop_id=sid, name=stops[sid]["stop_name"], timezone=btz(sid)[1],
                        service_date=ds, departures=[x for _, x in deps]))
    with open(outp, "w", encoding="utf-8") as f:
        json.dump(dict(service_dates=dates, boards=out), f, ensure_ascii=False)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
